import{_ as a,o as s,c as t,k as n}from"./chunks/framework.ystBm8og.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"develop/architecture.md","filePath":"develop/architecture.md","lastUpdated":1785751237000}'),o={name:"develop/architecture.md"};function i(r,e,d,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Pomodoro is a <strong>Tauri v2</strong> desktop app: Rust owns timer state, persistence, tray, and IPC; the UI is vanilla TypeScript + CSS rendered in a system webview.</p><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td>Shell</td><td>Tauri v2, multi-platform webview</td></tr><tr><td>Core</td><td>Rust - timer FSM, commands, tray</td></tr><tr><td>Storage</td><td><code>tauri-plugin-store</code> (settings, todos), <strong>rusqlite</strong> (sessions)</td></tr><tr><td>Frontend</td><td>TypeScript, Vite, no UI framework</td></tr><tr><td>Plugins</td><td>notification, store, opener, tray-icon</td></tr></tbody></table><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pomodoro/</span></span>
<span class="line"><span>├── src/                      # Frontend</span></span>
<span class="line"><span>│   ├── main.ts               # Bootstrap, title bar, sheets wiring</span></span>
<span class="line"><span>│   ├── state.ts              # Frontend store + invoke helpers</span></span>
<span class="line"><span>│   ├── ui/                   # Timer, controls, tasks, sessions, settings</span></span>
<span class="line"><span>│   └── styles/               # Design tokens + app CSS</span></span>
<span class="line"><span>├── src-tauri/</span></span>
<span class="line"><span>│   ├── src/</span></span>
<span class="line"><span>│   │   ├── main.rs           # App setup, plugins, state</span></span>
<span class="line"><span>│   │   ├── timer.rs          # Phase machine, durations, effects</span></span>
<span class="line"><span>│   │   ├── commands.rs       # IPC commands</span></span>
<span class="line"><span>│   │   ├── todos.rs          # Task list persistence</span></span>
<span class="line"><span>│   │   ├── db.rs             # SQLite open / schema</span></span>
<span class="line"><span>│   │   ├── sessions.rs       # Session insert / list / stats</span></span>
<span class="line"><span>│   │   └── tray.rs           # Menu bar tray</span></span>
<span class="line"><span>│   ├── capabilities/         # Tauri ACL (e.g. start_dragging)</span></span>
<span class="line"><span>│   └── tauri.conf.json       # Window, bundle, identity</span></span>
<span class="line"><span>└── .github/workflows/        # Release CI</span></span></code></pre></div><h2 id="timer-core" tabindex="-1">Timer core <a class="header-anchor" href="#timer-core" aria-label="Permalink to &quot;Timer core&quot;">​</a></h2><p>The Rust <code>Timer</code> keeps phase, remaining time, running/paused flags, and settings. Commands such as <code>start_timer</code>, <code>pause_timer</code>, <code>toggle_timer</code>, <code>skip_phase</code>, <code>reset_timer</code>, and <code>set_phase</code> mutate state and emit effects (notifications, session rows, UI events).</p><p>Phase completion fires a frontend event (<code>timer://phase-complete</code>) for the optional chime and works with the notification plugin.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li><strong><code>store</code></strong> - caches timer snapshot, settings, todos; <code>invoke</code>s Rust commands; applies accent/theme attributes on <code>#app</code>.</li><li><strong>Views</strong> - pure DOM classes (<code>TimerView</code>, <code>Controls</code>, <code>Segments</code>, <code>TodosPanel</code>, <code>SessionsPanel</code>, <code>SettingsPanel</code>).</li><li><strong>Sheets</strong> - iOS-style bottom sheets for Tasks, Sessions, and Settings.</li><li><strong>Window chrome</strong> - overlay title bar; <code>data-tauri-drag-region</code> so the window can be moved without a classic title bar.</li></ul><h2 id="data-model-sessions" tabindex="-1">Data model (sessions) <a class="header-anchor" href="#data-model-sessions" aria-label="Permalink to &quot;Data model (sessions)&quot;">​</a></h2><p>Session rows are stored in SQLite for the Sessions UI (stats, 7-day bars, recent list). Outcomes typically include completed, skipped, and stopped phases with timestamps and durations.</p><p>Settings and todos use the key-value store plugin (JSON files under the app data directory).</p><h2 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h2><p>Tauri capabilities in <code>src-tauri/capabilities/default.json</code> grant a minimal permission set (core, tray, notifications, opener, window <code>start_dragging</code>). Prefer adding permissions only when a feature needs them.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><ul><li>Bundle / product name: <strong>Pomodoro</strong></li><li>Identifier: <code>com.pomodoro.app</code></li></ul><h2 id="related-reading" tabindex="-1">Related reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related reading&quot;">​</a></h2><ul><li><a href="https://v2.tauri.app/" target="_blank" rel="noreferrer">Tauri v2 docs</a></li><li><a href="/develop/releasing">Releasing</a></li></ul>`,20)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
